import json

results = []
for item in items:
    content = item['json']['choices'][0]['message']['content']
    data = json.loads(content)

    if not data.get('valid', True):
        results.append({'json': {
            'valid': False,
            'reason': data.get('reason', 'nierozpoznane słowo'),
        }})
        continue

    results.append({'json': {
        'valid': True,
        'word': data['input_word'],
        'translation': data['translation'],
        'input_lang': data.get('input_lang', 'en'),
        'corrected_from': data.get('corrected_from', ''),
    }})

return results

parameters.jsCode:
const results = [];
for (const item of $input.all()) {
  const data = JSON.parse(item.json.choices[0].message.content);
  const t = $('Parse translation').first().json;
  const word = t.word;
  const translation = t.translation;
  const lang = t.input_lang;
  const ipa = data.ipa || '';
  const ex1 = data.example1;
  const ex1t = data.example1_translation;
  const ex2 = data.example2;
  const ex2t = data.example2_translation;
  const ex3 = data.example3;
  const ex3t = data.example3_translation;

  let front, back;
  if (lang === 'en') {
    front = `<b>${word}</b>  <i>${ipa}</i><br><br><ul><li>${ex1}</li><li>${ex2}</li><li>${ex3}</li></ul>`;
    back = `<b>${translation}</b><br><br><ul><li>${ex1t}</li><li>${ex2t}</li><li>${ex3t}</li></ul>`;
  } else {
    front = `<b>${word}</b><br><br><ul><li>${ex1}</li><li>${ex2}</li><li>${ex3}</li></ul>`;
    back = `<b>${translation}</b>  <i>${ipa}</i><br><br><ul><li>${ex1t}</li><li>${ex2t}</li><li>${ex3t}</li></ul>`;
  }

  results.push({ json: { front, back } });
}
return results;
